svg:
{%- if theme.dark %}








{%- endif %}

{#- The header: the title with its last word in italic, the runner's byline
    and the tracked subline in capitals. #}
  {{ title.head }}{% if title.tail %}{{ title.tail }}{% endif %}
  {{ runner }}
  {{ subline }}
{#- The picture. On dark paper a blurred copy of it goes first, so the
    shapes glow; the variant templates do not know. #}
{%- set viz %}{% block viz %}{% endblock %}{% endset %}
{%- if theme.dark %}
  {{ viz }}
{%- endif %}
  {{ viz }}



{%- for color in legend %}

{%- endfor %}

{#- resvg tracks after the last letter too, so the right-aligned caption is
    anchored 1.5 px further right to end with the bar. #}
  SLOWER
  FASTER
{#- The route in miniature on the row of the legend, flush right in the box
    x 472 to 672, y 750 to 806. Outside the picture, so it never glows. #}
{%- if route %}


{%- endif %}

{#- The stats line: each unit muted, after a space outside its tspan, since
    resvg drops a tspan's leading space. #}
  {{ time }}
  {{ stats.distance.value }} {{ stats.distance.unit }}
  {{ stats.pace.value }} {{ stats.pace.unit }}
{#- The fastest pace flush right, its label 14 px before it. On light paper
    a marker-pen stroke lies under the pace, on dark a blurred copy. #}
{%- if stats.fastest %}
{%- set fastest = stats.fastest %}
{%- set pace %}{{ fastest.pace }}{% endset %}
  {{ fastest.label }}
{%- if theme.dark %}
  {{ pace }}
{%- else %}

{%- endif %}
  {{ pace }}
{%- endif %}
